    console.log(dataList1.getMatchedJSON("col1", "가"));
    data = dataList1.getMatchedJSON("col1", "가");
    //alert(dataList1.getMatchedJSON("col1","가"));
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkSorting = function() {
    var k = 0;
    for (var i = 30; i >= 0; i--) {
        if (i == 19) {
            grid1.setBottomRowIndex(20);
            k = 0;
        }
        if (i == 10) {
            grid1.setBottomRowIndex(30);
            k = 0;
        }
        if (WebSquare.wUnit.getDomById($p.id + "grid1_cell_" + k + "_2").textContent == i) {
            k++;
            return true;
        } else {
            return false;
            break;
        }
    }
}
scwin.checkData = function(data) {
    for (var i = 0; i < data.length; i++) {
        if (data[i].col1 == "가") {
            return true;
        } else {
            return false;
            break;
        }
    }
}
scwin.setVal = function() {
    return scwin.checkData(data);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '금액'항목을 sorting한다.(마우스로 2번 더블클릭)
    //1. After running the sample, sort the 'Amount' item (double-click twice with the mouse).
    //Verify step 1. Sroting is done.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grid1_header4')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grid1_header4')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkSorting()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger10').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.setVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.data = undefined;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
